select i18n_set('app', (select slug from entities where type = 'app' and name = 'Co-Star' and is_published limit 1), 'fr', 'short_description', 'Application d''astrologie qui produit thèmes natals et horoscopes quotidiens à partir de données de la NASA, interprétés par des astrologues travaillant avec l''IA.', 'Astrology app that produces birth charts and daily horoscopes from NASA data, interpreted by human astrologers who work with AI technology.');
select i18n_set('app', (select slug from entities where type = 'app' and name = 'Rosebud AI' and is_published limit 1), 'fr', 'short_description', 'Plateforme web pour créer, jouer, remixer et partager des jeux avec un assistant IA, avec des crédits hebdomadaires gratuits et des formules mensuelles payantes.', 'Web platform for creating, playing, remixing and sharing games with an AI assistant, offering free weekly credits and paid monthly tiers.');
select i18n_set('app', (select slug from entities where type = 'app' and name = 'Oscar Stories' and is_published limit 1), 'fr', 'short_description', 'Application pour enfants qui génère avec l''IA des histoires du soir personnalisées où l''enfant est le héros, avec narration audio et vidéos.', 'Children''s app that generates personalized bedtime stories with AI, casting the child as the hero, with audio narration and story videos.');
select i18n_set('app', (select slug from entities where type = 'app' and name = 'Kahoot!' and is_published limit 1), 'fr', 'short_description', 'Plateforme de jeux de quiz pour jouer et créer des kahoots, avec des outils IA qui génèrent des quiz à partir de sujets, pages web, PDF ou notes manuscrites.', 'Quiz game platform for playing and creating kahoots, with AI tools that generate quizzes from topics, web pages, PDFs or handwritten notes.');

select theme, count(*) as apps from v_apps group by theme order by theme;
